<script>(()=>{const nav=document.querySelector('[data-e806-nav]');document.querySelector('[data-e806-toggle]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));const mega=document.querySelector('[data-e806-mega]');document.querySelectorAll('[data-e806-mega-trigger]').forEach(a=>{a.addEventListener('mouseenter',()=>mega?.classList.add('is-open'));a.addEventListener('focus',()=>mega?.classList.add('is-open'))});document.querySelector('[data-e806-mega-close]')?.addEventListener('click',()=>mega?.classList.remove('is-open'));document.querySelectorAll('[data-e806-tabs] button').forEach(btn=>btn.addEventListener('click',()=>{btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active')}));})();</script>


